CREATE FUNCTION population_top3000_202608_202609_v1.f01_role_extract_v4(body text,uri text,index_form text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $f$
DECLARE header text;typ text;seq text;fn text;valid boolean:=false;role text:='UNRESOLVED_NO_SGML_ENVELOPE';
BEGIN
 IF body ~* '^<DOCUMENT>[[:space:]]' AND position('<TEXT>' in body)>0
 AND (SELECT count(*) FROM regexp_matches(body,'<DOCUMENT>','gi'))=1
 AND (SELECT count(*) FROM regexp_matches(body,'</DOCUMENT>','gi'))=1
 AND body ~* '</TEXT>[[:space:]]*</DOCUMENT>[[:space:]]*$' THEN
 header:=split_part(body,'<TEXT>',1);
 typ:=btrim(substring(header from '(?i)<TYPE>([^<\r\n]+)'),E' \t\r\n');
 seq:=btrim(substring(header from '(?i)<SEQUENCE>([^<\r\n]+)'),E' \t\r\n');
 fn:=btrim(substring(header from '(?i)<FILENAME>([^<\r\n]+)'),E' \t\r\n');
 valid:=(SELECT count(*) FROM regexp_matches(header,'<TYPE>','gi'))=1
 AND (SELECT count(*) FROM regexp_matches(header,'<SEQUENCE>','gi'))=1
 AND (SELECT count(*) FROM regexp_matches(header,'<FILENAME>','gi'))=1 AND coalesce(fn=regexp_replace(uri,'^.*/','') AND seq~'^[1-9][0-9]*$' AND typ IS NOT NULL,false);
 IF valid AND typ LIKE 'EX-%' THEN role:='SGML_EXHIBIT';
 ELSIF valid AND typ=index_form AND seq='1' THEN role:='SGML_SEQUENCE1_FORM_DOCUMENT';
 ELSIF valid THEN role:='SGML_OTHER_DOCUMENT';ELSE role:='UNRESOLVED_HEADER_FILENAME_OR_SEQUENCE';END IF;
 END IF;
 RETURN jsonb_build_object('role_parser_revision','f01-retained-role-v4','document_type_from_body',typ,'document_sequence_from_body',seq,'filename_from_body',fn,'header_sha256',CASE WHEN header IS NOT NULL THEN encode(sha256(convert_to(header,'UTF8')),'hex') ELSE NULL END,'sgml_header_supported',valid,'document_role',role,'role_basis',CASE WHEN valid THEN 'EXACT_RETAINED_SGML_HEADER_AND_URI_FILENAME' ELSE 'INSUFFICIENT_RETAINED_HEADER' END,'issuer_role_verified',false,'primary_document_verified',false,'documents_exhibits_complete',false,'publication_time_verified',false,'historical_receipt_verified',false,'family_accepted',false);
END $f$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.f01_role_extract_v4(text,text,text) FROM PUBLIC,anon,authenticated;
