CREATE FUNCTION population_top3000_202608_202609_v1.f01_role_worker_v4(p_attempt uuid,p_token text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $f$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;z record;v jsonb;h text;out_hash text;source_hash text;n integer:=0;acc text;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 h:=t.input_versions->>'cohort_sha256';
 SELECT acceptance_sha256 INTO STRICT acc FROM population_top3000_202608_202609_v1.ref01_practical_membership_v1 WHERE snapshot_sha256=h AND acceptance_sha256=encode(sha256(convert_to(content::text,'UTF8')),'hex');
 IF t.family_id<>'F01' OR t.payload->>'kind' IS DISTINCT FROM 'PRACTICAL_F01_RETAINED_ROLES_V4' OR h IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' OR t.input_versions->>'policy_sha256' IS DISTINCT FROM '3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb' OR t.input_versions->>'membership_acceptance_sha256' IS DISTINCT FROM acc THEN RAISE EXCEPTION 'F01_FROZEN_POLICY_INPUT_MISMATCH';END IF;
 SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY source_id COLLATE "C",source_line_number),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 WHERE cohort_sha256=h AND acceptance_sha256=acc;
 IF out_hash IS DISTINCT FROM '90f21c07f4786ba465b22cd90a2716ebdeb04510792a3dec567d67653fff5dc4' OR out_hash IS DISTINCT FROM t.input_versions->>'filing_expectation_sha256' OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 WHERE cohort_sha256=h AND record_sha256<>encode(sha256(convert_to(content::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'F01_INDEX_INPUT_CHANGED';END IF;
 IF jsonb_typeof(t.payload->'sources') IS DISTINCT FROM 'array' OR jsonb_array_length(t.payload->'sources') IS DISTINCT FROM 22 OR t.input_versions->>'source_manifest_sha256' IS DISTINCT FROM '53d907dc033be71e5a9e6454fb75f68ab13483691a700367893558e72d976ed9' OR encode(sha256(convert_to((t.payload->'sources')::text,'UTF8')),'hex') IS DISTINCT FROM t.input_versions->>'source_manifest_sha256' THEN RAISE EXCEPTION 'F01_PINNED_SOURCES_CHANGED';END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(t.payload->'sources') pin JOIN population_top3000_202608_202609_v1.source_document d ON d.source_id=pin.value->>'source_id')<>22 THEN RAISE EXCEPTION 'F01_PINNED_SOURCE_MISSING';END IF;
 IF t.stage='VALIDATE' THEN RETURN jsonb_build_object('state','BLOCKED','blocker_code','F01_FULL_HEADER_ISSUER_ROLE_PUBLICATION_COMPLETENESS_REQUIRED_V4','resumption_condition',jsonb_build_object('cohort_sha256',h,'policy_sha256',t.input_versions->>'policy_sha256','membership_acceptance_sha256',acc,'engineering_successor_event_ids',t.input_versions->'engineering_successor_event_ids','retained_document_links',22,'issuer_roles_verified',false,'publication_times_verified',false,'all_documents_exhibits_verified',false,'prewindow_support_verified',false,'family_accepted',false));END IF;
 IF t.stage<>'DERIVE' THEN RAISE EXCEPTION 'F01_DERIVE_STAGE_REQUIRED';END IF;
 FOR z IN SELECT e.company_id,e.accession_number,e.source_line_number,e.content index_content,d.*,pin.value pin FROM jsonb_array_elements(t.payload->'sources') pin JOIN population_top3000_202608_202609_v1.source_document d ON d.source_id=pin.value->>'source_id' JOIN population_top3000_202608_202609_v1.ref01_practical_filing_expectation_v1 e ON e.source_line_number=(pin.value->>'source_line_number')::int AND e.cohort_sha256=h AND e.acceptance_sha256=acc ORDER BY e.source_line_number,d.source_id LOOP
  IF z.content_text IS NULL OR z.source_provider<>'SEC' OR z.company_id IS DISTINCT FROM z.pin->>'company_id' OR z.accession_number IS DISTINCT FROM z.pin->>'accession_number' OR z.source_uri IS DISTINCT FROM z.pin->>'source_uri' OR z.source_sha256 IS DISTINCT FROM z.pin->>'source_sha256' OR encode(sha256(convert_to(z.content_text,'UTF8')),'hex') IS DISTINCT FROM z.source_sha256 OR octet_length(z.content_text) IS DISTINCT FROM (z.pin->>'content_bytes')::bigint OR substring(z.source_uri from '/data/[0-9]+/([0-9]{18})/') IS DISTINCT FROM replace(z.accession_number,'-','') THEN RAISE EXCEPTION 'F01_ORIGINAL_BODY_OR_ASSOCIATION_MISMATCH';END IF;
  v:=jsonb_build_object('cohort_sha256',h,'policy_sha256',t.input_versions->>'policy_sha256','membership_acceptance_sha256',acc,'company_id',z.company_id,'accession_number',z.accession_number,'source_line_number',z.source_line_number,'source_id',z.source_id,'source_uri',z.source_uri,'source_sha256',z.source_sha256,'body_bytes',octet_length(z.content_text),'body_rehashed',true,'index_form',z.index_content->>'form','index_filing_date',z.index_content->>'filing_date','document_type_from_body',substring(z.content_text from '(?i)<TYPE>([^<\r\n]+)'),'filename_from_body',substring(z.content_text from '(?i)<FILENAME>([^<\r\n]+)'),'uri_filename',regexp_replace(z.source_uri,'^.*/',''),'association_basis','EXACT_ACCESSION_FROM_RETAINED_SOURCE_URI_AND_SELECTED_ISSUER_INDEX_ROW','document_class',CASE WHEN z.source_uri LIKE '%-index.htm' THEN 'FILING_INDEX_PAGE' WHEN lower(z.source_uri) LIKE '%.xml' THEN 'XML_SOURCE' WHEN substring(z.content_text from '(?i)<TYPE>([^<\r\n]+)') LIKE 'EX-%' THEN 'EXHIBIT' ELSE 'RETAINED_DOCUMENT_UNCLASSIFIED' END,'issuer_role_verified',false,'primary_document_verified',false,'documents_exhibits_complete',false,'publication_time_verified',false,'historical_received_at',z.historical_received_at,'retrieved_at',z.retrieved_at,'historical_receipt_verified',false,'prewindow_support_complete',false,'family_accepted',false);
  v:=v||population_top3000_202608_202609_v1.f01_role_extract_v4(z.content_text,z.source_uri,z.index_content->>'form');
  INSERT INTO population_top3000_202608_202609_v1.f01_practical_document_role_v4 VALUES(h,z.company_id,z.accession_number,z.source_id,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
  IF FOUND THEN n:=n+1;END IF;
  IF (SELECT content FROM population_top3000_202608_202609_v1.f01_practical_document_role_v4 WHERE cohort_sha256=h AND company_id=z.company_id AND accession_number=z.accession_number AND source_id=z.source_id) IS DISTINCT FROM v THEN RAISE EXCEPTION 'F01_REPLAY_CONFLICT';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.f01_practical_document_role_v4 WHERE cohort_sha256=h AND record_sha256 IS DISTINCT FROM encode(sha256(convert_to(content::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'F01_RECORD_HASH_CHANGED';END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.f01_practical_document_role_v4 WHERE cohort_sha256=h)<>22 THEN RAISE EXCEPTION 'F01_RETAINED_SOURCE_SHORTFALL';END IF;
 SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n' ORDER BY company_id COLLATE "C",accession_number COLLATE "C",source_id COLLATE "C"),'UTF8')),'hex') INTO out_hash FROM population_top3000_202608_202609_v1.f01_practical_document_role_v4 WHERE cohort_sha256=h;
 RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','f01-retained-roles-v4:'||h||':'||(t.input_versions->>'source_manifest_sha256'),'output_sha256',out_hash,'new_committed_units',n,'immutable_output_ids',jsonb_build_array(out_hash),'input_versions',t.input_versions,'retained_document_links',22,'selected_companies_linked',12,'engineering_successor_event_ids',t.input_versions->'engineering_successor_event_ids','issuer_role_verified',false,'family_accepted',false));
END $f$;
